CustomField.formula:
If(
    Full_CXP__c!="No", "01 - Full CXP", 
if(
    MC_Digital__c=false && MC_Retention__c && MC_Website__c=false, 
        If(Category_Sales_Retention_Active__c || Category_Service_Retention_Active__c, "03 - Retention Only", "05 - Mail Only"),
if(
    MC_Digital__c && (Category_Sales_Retention_Active__c || Category_Service_Retention_Active__c), "05 - Digital & Retention",
if(
    (Category_Sales_Retention_Active__c || Category_Service_Retention_Active__c) && MC_Website__c, "05 - Retention & Website",
if(
    MC_Digital__c && MC_Website__c, "05 - Digital & Website",
if(
    MC_Digital__c && (Category_Sales_Retention_Active__c || Category_Service_Retention_Active__c)=false, "02 - Digital Only",
if(
    MC_Website__c, "04 - Website Only - "&Portal_or_Primary_Website__c,
if(
    PP_OTT_Dynamic_Active__c || PP_OTT_Dynamic_Active__c, "06 - OTT Only",
    "Other"
))))))))
